def min_operations_to_equal(arr, k):
    n = len(arr)
    if n == 0:
        return 0
    arr_sorted = sorted(arr)
    median = arr_sorted[n // 2]
    operations = 0
    for x in arr:
        diff = abs(x - median)
        if diff % k != 0:
            return -1
        operations += diff

```python
def min_operations_to_equal(arr, k):
    if not arr:
        return 0
    target = max(arr)
    total = 0
    for x in arr:
        diff = target - x
        if diff % k != 0:
            return -1
        total += diff // k
    return total
```

