def largest_adjacent_product(nums):
    if len(nums) < 2:
        return None

    largest = nums[0] * nums[1]

    for i in range(1, len(nums) - 1):
        product = nums[i] * nums[i + 1]
        if product > largest:
            largest = product

    return largest
```

